use super::*;
use crate::schema::scene_preparation::DocumentSceneContent;
use serde_json::Value;
fn rows()->Vec<Value>{serde_json::from_str(include_str!("../../../../🧬️schema/🎬️scene/📋️prepare/🧫️fixtures/🎬️vector/🔣️.json")).unwrap()}
fn install(render:AppRenderOperationContext,read:store::SnapshotRead<DrawingSnapshot>)->(usize,u64){let effects=reconcile_source(render,||Ok(read));match effects.last().unwrap(){Effect::SpawnJob{job,input,..}=>(usize::from(u16::from_le_bytes(input[1..3].try_into().unwrap())),*job),_=>panic!("the production reconciliation must spawn the prepared geometry job")}}

fn drive(job:&mut dyn BoundedJob)->bool{for _ in 0..1000000{match job.step(JobBudget{fuel:1,deadline_ms:8}){JobStep::Running(_)=>{},JobStep::Done(_)=>return true,JobStep::Failed(_)=>return false}}panic!("mounted geometry did not settle")}
async fn source(row:&Value)->store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>{let document:DrawingSnapshot=serde_json::from_value(row["document"].clone()).unwrap();let mut source=store::ArtifactStore::new(store::create_document_envelope::<DrawingSnapshot,crate::op::DrawingMutation>("drawing.drawing","mounted-vector",document,None)).await.unwrap();source.install_document_store_owners_exact(crate::spr::drawing_document_store_owners());source}
fn return_reads(source:&mut store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>){if let Some(mut returned)=source.take_returned_snapshot_read_retirement().unwrap(){for _ in 0..100000{if returned.terminal_is_empty(){return;}returned.close_step(1,4096).unwrap();}panic!("source return did not settle");}}
fn finish(instance:u32,source:&mut store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>){for _ in 0..1000000{close(instance,1,4096);return_reads(source);if terminal_is_empty(instance){break;}}assert!(terminal_is_empty(instance));for _ in 0..100000{if store::SpaceMember::close_owned_terminal_is_empty(source){break;}store::SpaceMember::close_owned_step(source,1,4096).unwrap();}assert!(store::SpaceMember::close_owned_terminal_is_empty(source));}
fn render(source:&store::ArtifactStore<DrawingSnapshot,crate::op::DrawingMutation>,instance:u32,base:u64)->AppRenderOperationContext{AppRenderOperationContext{app_instance_id:instance,base_revision:semio_framework_job::RevisionId(base),generation:semio_framework_job::Generation(source.generation()),canonical_base_revision:source.content_revision()}}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_query_borrows_only_exact_complete_geometry_and_refuses_superseded_source(){
 let row=rows().remove(0);let mut source=source(&row).await;let first=render(&source,710011,9007199254740993);let captured=identity(first);let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));
 assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);let(slot,job)=install(first,read);let mut worker=factory(job,&input(slot,captured,job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);
 let pointer=with_visual(Some(first),|plan,_,_|plan.unwrap().nodes.as_ptr());with_query(captured,|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);assert_eq!(plan.unwrap().nodes.as_ptr(),pointer,"queries borrow the actual complete visual without a plan clone");});
 let shell=MOUNTED.with(|r|r.borrow().shells[slot].clone());let checked_out=shell.borrow_mut();assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);drop(checked_out);
 let replacement=render(&source,first.app_instance_id,9007199254740992);let read=source.snapshot_read().unwrap();assert!(prepare(replacement,read.get()));assert_eq!(with_query(captured,|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Stale);assert_eq!(with_query(identity(replacement),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);
 let(next,new_job)=install(replacement,read);let mut worker=factory(new_job,&input(next,identity(replacement),new_job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);with_query(identity(replacement),|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);assert!(plan.is_some());});finish(first.app_instance_id,&mut source);assert_eq!(with_query(identity(replacement),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Stale);
 eprintln!("[DEBUG] Actual mounted query observed pending work, borrowed the exact complete visual, yielded around a checked-out owner and refused superseded full-width source lanes and a closed instance");
}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_query_preserves_real_failure_after_candidate_retirement_and_recovers_on_new_source(){
 let row=rows().remove(0);let mut source=source(&row).await;let mut failed=render(&source,710012,11);failed.generation.0+=1;let read=source.snapshot_read().unwrap();assert!(prepare(failed,read.get()));let(slot,job)=install(failed,read);let mut worker=factory(job,&input(slot,identity(failed),job),None).unwrap();assert!(!drive(worker.as_mut()));drop(worker);
 assert_eq!(with_query(identity(failed),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Failed);
 for _ in 0..100000{maintenance(failed.app_instance_id,1,4096);return_reads(&mut source);if MOUNTED.with(|r|r.borrow().shells[slot].borrow().is_none()){break;}}
 assert!(MOUNTED.with(|r|r.borrow().shells[slot].borrow().is_none()));assert_eq!(with_query(identity(failed),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Failed,"cleanup must not turn a failed source into an endless pending query");
 let live=render(&source,failed.app_instance_id,12);let read=source.snapshot_read().unwrap();assert!(prepare(live,read.get()));assert_eq!(with_query(identity(live),|status,plan|{assert!(plan.is_none());status}),SceneAdmissionStatus::Pending);let(slot,job)=install(live,read);let mut worker=factory(job,&input(slot,identity(live),job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);with_query(identity(live),|status,plan|{assert_eq!(status,SceneAdmissionStatus::Ready);assert!(plan.is_some());});finish(live.app_instance_id,&mut source);
 eprintln!("[DEBUG] Actual producer source refusal persisted through all candidate/source-return cleanup, then a genuinely admitted replacement recovered with complete borrowed geometry");
}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_drives_real_source_and_exact_complete_canvas(){
 for row in rows(){let mut source=source(&row).await;let render=render(&source,700007,11);let read=source.snapshot_read().unwrap();assert!(prepare(render,read.get()));let(slot,job)=install(render,read);assert!(with_visual(Some(render),|plan,_,_|plan.is_none()));let mut worker=factory(job,&input(slot,identity(render),job),None).unwrap();assert!(worker.terminal_drop_is_shallow());assert!(drive(worker.as_mut()));
 with_visual(Some(render),|plan,revision,fresh|{let plan=plan.unwrap();assert!(fresh);assert_eq!(u64::from(revision),job&COUNTER_MAX);assert!(plan.nodes.iter().all(|n|!matches!(n.content,DocumentSceneContent::Boolean{..}|DocumentSceneContent::Trace{..})));let views=crate::schema::scene_view::nodes(plan,None).unwrap();for view in &views{if let Some(node)=plan.nodes.iter().find(|node|node.id==view.id){if let DocumentSceneContent::Path{segments,..}=&node.content{assert_eq!(view.segments.as_ptr(),segments.as_ptr(),"canvas borrows the actual completed geometry");}}}let tree=super::super::canvas_window::render(Some(plan),revision,&serde_json::from_value(row["document"].clone()).unwrap(),&Default::default(),&Default::default(),"selectDirect",&[],&[]).unwrap();let _=tree;});drop(worker);finish(render.app_instance_id,&mut source);eprintln!("[DEBUG] Mounted vector source {} published complete borrowed canvas geometry and retired its genuine read",row["name"]);
 }
}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_retains_complete_picture_and_refuses_superseded_factory(){
 let row=rows().remove(0);let mut source=source(&row).await;let first=render(&source,700008,11);let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));let(slot,job)=install(first,read);let bytes=input(slot,identity(first),job);let mut worker=factory(job,&bytes,None).unwrap();assert!(drive(worker.as_mut()));drop(worker);
 let mut replacement=first;replacement.base_revision.0+=1;replacement.generation.0+=1;let read=source.snapshot_read().unwrap();assert!(prepare(replacement,read.get()));let(next,new_job)=install(replacement,read);assert_eq!(with_visual(Some(replacement),|_,revision,_|revision), (job&COUNTER_MAX)as u32,"the completed picture survives replacement preparation");let mut worker=factory(new_job,&input(next,identity(replacement),new_job),None).unwrap();assert!(!drive(worker.as_mut()),"genuine store authority refuses a forged generation");assert_eq!(with_visual(Some(replacement),|_,revision,_|revision), (job&COUNTER_MAX)as u32);drop(worker);
 assert!(factory(job+1,&bytes,None).is_err());assert!(factory(job,&bytes[..62],None).is_err());finish(first.app_instance_id,&mut source);assert!(factory(job,&bytes,None).is_err());eprintln!("[DEBUG] Mounted vector replacement kept the complete picture, rejected genuine-source generation mismatch and refused stale factories after terminal close");
}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_cancellation_owns_partial_children_until_return(){let row=rows().pop().unwrap();for steps in [0,1,12,80]{let mut source=source(&row).await;let render=render(&source,700009,11);let read=source.snapshot_read().unwrap();assert!(prepare(render,read.get()));let(slot,job)=install(render,read);let mut worker=factory(job,&input(slot,identity(render),job),None).unwrap();for _ in 0..steps{worker.step(JobBudget{fuel:1,deadline_ms:8});}worker.cancel();assert!(!drive(worker.as_mut()));assert!(with_visual(Some(render),|plan,_,_|plan.is_none()));drop(worker);finish(render.app_instance_id,&mut source);eprintln!("[DEBUG] Mounted vector cancellation at {steps} real producer units drained actual partial child owners and source return witness");}}

#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_failed_slot_is_not_owned_by_its_previous_instance(){let row=rows().remove(0);let mut source=source(&row).await;let mut first=render(&source,700010,11);first.generation.0+=1;let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));let(slot,job)=install(first,read);let mut worker=factory(job,&input(slot,identity(first),job),None).unwrap();assert!(!drive(worker.as_mut()));drop(worker);for _ in 0..1000{maintenance(first.app_instance_id,1,4096);return_reads(&mut source);let empty=MOUNTED.with(|r|r.borrow().shells[slot].borrow().is_none());if empty{break;}}MOUNTED.with(|r|{let r=r.borrow();assert!(r.shells[slot].borrow().is_none());assert!(r.instances[first.app_instance_id as usize%INSTANCES].unwrap().candidate.is_none(),"a retired failed candidate cannot retain authority over a reusable shell");});let second=render(&source,700011,12);let read=source.snapshot_read().unwrap();assert!(prepare(second,read.get()));let(next,new_job)=install(second,read);assert_eq!(slot,next,"the fixed arena really reused the retired slot");close(first.app_instance_id,1,4096);let mut worker=factory(new_job,&input(next,identity(second),new_job),None).unwrap();assert!(drive(worker.as_mut()),"closing the first instance cannot cancel the reused slot");drop(worker);finish(second.app_instance_id,&mut source);assert!(terminal_is_empty(first.app_instance_id));eprintln!("[DEBUG] Failed mounted candidate relinquished its exact shell before another instance reused it; previous close did not cancel the new owner");}
#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_reconciliation_cancels_the_actual_superseded_private_owner(){let row=rows().pop().unwrap();let mut source=source(&row).await;let first=render(&source,700012,11);let read=source.snapshot_read().unwrap();assert!(prepare(first,read.get()));let(slot,job)=install(first,read);let mut old=factory(job,&input(slot,identity(first),job),None).unwrap();old.step(JobBudget{fuel:1,deadline_ms:8});let second=render(&source,first.app_instance_id,12);let read=source.snapshot_read().unwrap();assert!(prepare(second,read.get()));let effects=reconcile_source(second,||Ok(read));assert!(matches!(effects.first(),Some(Effect::CancelJob{job:old_job})if *old_job==job));let Some(Effect::SpawnJob{job,input,..})=effects.last()else{panic!("replacement must spawn after cancellation")};let mut replacement=factory(*job,input,None).unwrap();assert!(!drive(old.as_mut()));assert!(drive(replacement.as_mut()));drop(old);drop(replacement);finish(first.app_instance_id,&mut source);eprintln!("[DEBUG] Production reconciliation emitted actual private cancellation before isolated replacement spawn and retained both real source leases through terminal cleanup");}

#[semio_framework_async_macros::async_test]
async fn mounted_vector_geometry_real_edit_replaces_only_complete_live_geometry(){
 let row=rows().remove(0);let mut source=source(&row).await;let first=render(&source,700013,11);let read=source.snapshot_read().unwrap();let layer=crate::schema::layer_base(&read.get().layers[0]).id.clone();assert!(prepare(first,read.get()));let(slot,job)=install(first,read);let mut worker=factory(job,&input(slot,identity(first),job),None).unwrap();assert!(drive(worker.as_mut()));drop(worker);
 let pending=render(&source,first.app_instance_id,12);let read=source.snapshot_read().unwrap();assert!(prepare(pending,read.get()));let(slot,pending_job)=install(pending,read);let mut outdated=factory(pending_job,&input(slot,identity(pending),pending_job),None).unwrap();assert!(matches!(outdated.step(JobBudget{fuel:1,deadline_ms:8}),JobStep::Running(_)));
 source.apply_one(source.generation(),crate::mutations::delete_layer(layer.clone()),Some("Delete mounted vector layer".into()),store::HistoryLane::Document).await.unwrap();let live=render(&source,first.app_instance_id,13);assert_ne!(live.generation,first.generation);assert_ne!(live.canonical_base_revision,first.canonical_base_revision);assert!(!drive(outdated.as_mut()),"an actual document edit invalidates the captured source authority");drop(outdated);
 with_visual(Some(live),|plan,revision,fresh|{assert!(!fresh);assert_eq!(u64::from(revision),job&COUNTER_MAX);assert!(plan.unwrap().nodes.iter().any(|node|node.id==layer),"the last complete picture remains until its replacement is ready");});
 let read=source.snapshot_read().unwrap();assert!(read.get().layers.is_empty());assert!(prepare(live,read.get()));let(slot,new_job)=install(live,read);let mut replacement=factory(new_job,&input(slot,identity(live),new_job),None).unwrap();assert!(drive(replacement.as_mut()));drop(replacement);
 with_visual(Some(live),|plan,revision,fresh|{assert!(fresh);assert_eq!(u64::from(revision),new_job&COUNTER_MAX);assert!(plan.unwrap().nodes.is_empty());});finish(first.app_instance_id,&mut source);eprintln!("[DEBUG] A real event-sourced deletion invalidated in-flight source authority, preserved the completed picture during replacement, published only live replacement geometry and acknowledged all source reads");
}
